rule.rule_attribute:
{%- set found = false -%}
                              {%- if propValue is not empty -%}
                              {%- set toReplace = [ "Ä"
                              , "Ö"
                              , "Ü"
                              , "?"
                              , "Å"
                              , "Æ"
                              , "Ø"
                              , "ä"
                              , "ö"
                              , "ü"
                              , "ß"
                              , "å"
                              , "æ"
                              , "ø" ] -%}
                              {%- for item in toReplace -%}
                              {%- if (not found) -%}
                              {%- if (propValue contains item) -%}
                              {%- set found = true -%}
                              {%- endif -%}
                              {%- endif -%}
                              {%- endfor -%}
                              {%- endif -%}
                              {{- found -}}

{%- set connection = closestConnection(transformationColumn) -%}
                          {%- set schemaName = null -%}
                          {%- set tableName = null -%}
                          {%- if table.sourceTables | length == 1 -%}
                          {%- set schemaName = table.sourceTables[0].schema -%}
                          {%- set tableName = table.sourceTables[0].name -%}
                          {%- endif -%}
                          '{%- if connection is not null -%}{{ connection.name }}{%- endif -%}
                          {%- if schemaName is not empty -%}.{{ schemaName }}{%- endif -%}
                          {%- if tableName is not empty -%}.{{ tableName }}{%- endif -%}'

{%- declare result = false -%}
                              {%- set connection = closestConnection(table) -%}
                              {%- if connection is not null -%}
                              {%- if connection.connectionType == "Host" -%}
                              {%- set result = true -%}
                              {%- endif -%}
                              {%- endif -%}
                              {{- result -}}

{%- set result = false -%}
                              {%- for SSet in table.sourceSets -%}
                              {%- if not (SSet.dwQuery is empty) -%}
                              {%- set result = true -%}
                              {%- endif -%}
                              {%- endfor -%}
                              {{- result -}}
